import heapq

class Solution:
    def minTimeToBuildBlocks(self, blocks: list[int], split: int) -> int:
        heapq.heapify(blocks)
        while len(blocks) > 1:
            _b1 = heapq.heappop(blocks)
            b2 = heapq.heappop(blocks)
            heapq.heappush(blocks, b2 + split)
        return blocks[0]

class Solution {
public:
    int minTimeToBuildBlocks(std::vector<int>& blocks, int split) {
        std::priority_queue<int, std::vector<int>, std::greater<int>> pq(blocks.begin(), blocks.end());
        while (pq.size() > 1) {
            pq.pop();
            int b2 = pq.top();
            pq.pop();
            pq.push(b2 + split);
        }
        return pq.top();
    }
};

class Solution {
    public int minTimeToBuildBlocks(int[] blocks, int split) {
        java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>();
        for (int b : blocks) pq.add(b);
        while (pq.size() > 1) {
            pq.poll();
            int b2 = pq.poll();
            pq.add(b2 + split);
        }
        return pq.peek();
    }
}

var minTimeToBuildBlocks = function(blocks, split) {
    blocks.sort((a, b) => a - b);
    while (blocks.length > 1) {
        blocks.shift();
        const b2 = blocks.shift();
        const combined = b2 + split;
        let l = 0, r = blocks.length;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (blocks[mid] < combined) l = mid + 1;
            else r = mid;
        }
        blocks.splice(l, 0, combined);
    }
    return blocks[0];
};
